import{_ as r,l,o as e,c as n,v as t,p as s,x as o,d as M,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"IOMMU","description":"","frontmatter":{"title":"IOMMU","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/iommu.md","filePath":"cs/iommu.md","lastUpdated":1789023840000}'),A={name:"cs/iommu.md"};function I(p,a,c,O,h,u){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="iommu" tabindex="-1">IOMMU <a class="header-anchor" href="#iommu" aria-label="Permalink to &quot;IOMMU&quot;">​</a></h1><div class="epigraph"><p>IOMMU 给设备一张自己的页表：DMA 使用 I/O 虚地址，内核限制设备能写到哪些物理页。</p><footer>—— 据 AMD/Intel IOMMU 架构概述；Tanenbaum 对 DMA 保护的整理</footer></div><p><a href="/cs/io-dma">上一课</a>让设备按物理地址写帧，并点到 IOMMU。<a href="/cs/paging-vm">分页</a> 保护的是 CPU 路径；设备作为总线主设备不走用户页表。缺口是<strong>设备翻译与隔离</strong>：错误的描述符或恶意设备不应写任意 DRAM。本课讲机制，不写攻击步骤。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无 IOMMU：DMA 地址 = 物理地址（或 bounce）。外设或驱动 bug 可以覆写内核。有 IOMMU：驱动为一次传输建立 IOVA→PA 映射，设备只看见 IOVA。传输结束解映射。缺口不是重导 CPU 页表格式，而是：另一套翻译对象，权限更粗，与 <a href="/cs/tlb-translate">TLB</a> 类似也有 IOTLB，失效要 shootdown 设备侧缓冲。</p><p>本课不把 VT-d 与 AMD-Vi 的寄存器级编程当考纲。</p><p><span class="marginnote">VFIO/设备直通把 IOMMU 分组借给客机，虚拟化课会再提。这里只要求：CPU 分页管 CPU，IOMMU 管设备。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>驱动：dma_map 把 bio 的页做成 IOVA，填入设备描述符。IOMMU 硬件按设备源 ID 选上下文表，走 I/O 页表。非法 IOVA 可中止并中断。完成：dma_unmap，IOTLB 作废。与 buddy 钉页规则同时成立：映射期间页不得被置换。</p>',9)),(e(),s(m,null,{default:o(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E8%AE%BE%E5%A4%87%20DMA%22%5D%20--%3E%20IOVA%5B%22I%2FO%20%E8%99%9A%E5%9C%B0%E5%9D%80%22%5D%0A%20%20IOVA%20--%3E%20IOPT%5B%22IOMMU%20%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20IOPT%20--%3E%20PA%5B%22%E5%85%81%E8%AE%B8%E7%9A%84%E7%89%A9%E7%90%86%E9%A1%B5%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[M(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>IOMMU 把 DMA 从「信任设备」改成「设备也有地址空间」。这与用户/内核分裂平行：都是翻译上的权限，主体不同。性能代价是映射建立与 IOTLB 缺失。不要在此写如何绕过 IOMMU。</p><p>块层 bio 仍描述页；IOMMU 是 DMA API 之下的翻译。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ATS/PRI 等 PCIe 扩展全文。不保证所有平台有 IOMMU 或已开启。下一课离开块与 DMA，进入进程间的异步通知：信号。</p><p>后课默认：设备 DMA 可被限制在映射过的页。针对进程的软件中断，下一课信号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IOMMU 为 DMA 提供 IOVA 翻译与设备隔离。</li><li>映射期必须钉页；IOTLB 要作废。</li><li>进程级异步事件是信号课的缺口。</li><li>出处：Intel VT-d / AMD-Vi 概述；Tanenbaum <em>MOS</em>；Linux DMA API。</li></ul>',8))])}const D=r(A,[["render",I]]);export{T as __pageData,D as default};
